INSERT INTO `clob_datatype_storage` VALUES
(1,'6ecf5e48-ddb0-442b-abdd-b1da53eddca5','{\n  \"name\": \"Mental Health Assessment Form\",\n  \"version\": \"1\",\n  \"published\": true,\n  \"retired\": false,\n  \"pages\": [\n    {\n      \"label\": \"PHQ-2 Screening\",\n      \"sections\": [\n        {\n          \"label\": \"Introduction\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"markdown\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"id\": \"phq9Intro\",\n              \"value\": [\n                \"**PHQ-9 Depression Screening**\",\n                \"\",\n                \"This form is used for screening, diagnosing, monitoring and measuring the severity of depression.\",\n                \"\",\n                \"**Instructions:** Over the last 2 weeks, how often have you been bothered by any of the following problems?\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Patient Health Questionnaire-2 (PHQ-2)\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"label\": \"Screening Date\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"160753AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"160753\"\n                  },\n                  {\n                    \"type\": \"SNOMED-CT\",\n                    \"value\": \"439771001\"\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  },\n                  \"validators\": [\n                    {\n                      \"type\": \"date\",\n                      \"allowFutureDates\": \"false\"\n                    },\n                    {\n                      \"type\": \"js_expression\",\n                      \"failsWhenExpression\": \"isDateBefore(myValue, \'1980-01-01\')\"\n                    }\n                  ]\n                }\n              ],\n              \"id\": \"phq9Date\"\n            },\n            {\n              \"label\": \"1. Little interest or pleasure in doing things\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167006AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167006\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44250-9\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq2_1\"\n            },\n            {\n              \"label\": \"2. Feeling down, depressed or hopeless\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167007AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167007\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44255-8\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq2_2\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"PHQ-9 Additional Questions\",\n      \"sections\": [\n        {\n          \"label\": \"Further evaluation\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"label\": \"3. Trouble falling asleep, staying asleep, or sleeping too much\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167068AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44259-0\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167068\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_3\"\n            },\n            {\n              \"label\": \"4. Feeling tired or having little energy\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167069AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44254-1\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167069\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_4\"\n            },\n            {\n              \"label\": \"5. Poor appetite or overeating\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167070AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167070\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44251-7\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_5\"\n            },\n            {\n              \"label\": \"6. Feeling bad about yourself - or that you\'re a failure or have let yourself or your family down\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167071AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167071\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44258-2\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_6\"\n            },\n            {\n              \"label\": \"7. Trouble concentrating on things, such as reading the newspaper or watching television\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167072AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44252-5\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167072\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_7\"\n            },\n            {\n              \"label\": \"8. Moving or speaking so slowly that other people could have noticed. Or, the opposite - being so fidgety or restless that you have been moving around a lot more than usual\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167073AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167073\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44253-3\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_8\"\n            },\n            {\n              \"label\": \"9. Thoughts that you would be better off dead or of hurting yourself in some way\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167074AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167074\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44260-8\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"hide\": {\n                    \"hideWhenExpression\": \"false\"\n                  }\n                }\n              ],\n              \"id\": \"phq9_9\"\n            }\n          ]\n        }\n      ],\n      \"behaviours\": [\n        {\n          \"intent\": \"*\",\n          \"hide\": {\n            \"hideWhenExpression\": \"phq2_1 === \'160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' && phq2_2 === \'160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'\"\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Scoring and Results\",\n      \"sections\": [\n        {\n          \"label\": \"PHQ-9 Scoring\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"label\": \"PHQ-2 Score (Questions 1-2)\",\n              \"type\": \"control\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"max\": \"6\",\n                \"min\": \"0\",\n                \"calculate\": {\n                  \"calculateExpression\": \"calcPHQ9Score(phq2_1, phq2_2)\"\n                }\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"readonly\": \"true\"\n                }\n              ],\n              \"id\": \"phq2Score\"\n            },\n            {\n              \"label\": \"PHQ-9 Total Score (Questions 1-9)\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"165137AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"max\": \"27\",\n                \"min\": \"0\",\n                \"calculate\": {\n                  \"calculateExpression\": \"calcPHQ9Score(phq2_1, phq2_2, phq9_3, phq9_4, phq9_5, phq9_6, phq9_7, phq9_8, phq9_9)\"\n                },\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"SNOMED-CT\",\n                    \"value\": \"720433000\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"165137\"\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"readonly\": \"true\"\n                }\n              ],\n              \"id\": \"phq9TotalScore\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Notes\",\n      \"sections\": [\n        {\n          \"label\": \"Additional Notes\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"label\": \"Clinician Notes\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"textarea\",\n                \"concept\": \"165095AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"rows\": \"\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"AMPATH\",\n                    \"value\": \"1915\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"48767-8\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"160632\"\n                  }\n                ]\n              },\n              \"id\": \"clinicianNotes\"\n            }\n          ]\n        }\n      ]\n    }\n  ],\n  \"availableIntents\": [\n    {\n      \"intent\": \"*\",\n      \"display\": \"Mental Health Assessment Form\"\n    }\n  ],\n  \"processor\": \"EncounterFormProcessor\",\n  \"uuid\": \"2069bd57-d534-3de9-ae24-f1d4e4b2de83\",\n  \"referencedForms\": [],\n  \"encounterType\": \"36db5123-0ad5-41c0-9037-625b46e0ceef\",\n  \"encounter\": \"Mental Health Assessment\",\n  \"description\": \"A form used for screening, diagnosing, monitoring and measuring the severity of depression\"\n}'),
