INSERT INTO `global_property` VALUES
('@openmrs/esm-fast-data-entry-app.groupSessionVisitTypeUuid','78370d15-38ad-48a1-825f-f0e9ff60d5a1','UUID of the visit type used by Fast Data Entry to create visits when in \'group sessions\' entry workflow','b0784100-cfa3-4af0-a219-58baf94bbc9b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.addressToEntryMapUpdaterLastStartTime',NULL,'The module uses this field to store when the AddressToEntryMapUpdater task was last started; DO NOT MODIFY','5c0e30aa-aa52-4fea-bf75-75e9d0efc866',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.allowFreetext','true','Valid values: true/false. When overriding the address portlet, allow the entry of free text for address fields associated with the address hierarchy by providing an \"Other\" option','1f535af2-c62f-4bf9-99fb-a8fa6ef638d3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.enableOverrideOfAddressPortlet','true','Valid values: true/false. When enabled, the existing \"edit\" component of the address portlet is overridden by the new functionality provided by the address hierarchy module','a8cd4dc5-ad3e-4490-badd-fc0fe920f9c8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.initializeAddressHierarchyCacheOnStartup','true','Sets whether to initialize the address hierarchy in-memory cache (which is used to speed up address hierarchy searches.\nGenerally, you want to set this to \"true\", though developers may want to set it to false during development\nto speed module start-up.','98535e50-dddb-4921-89cf-b5c97075d3c6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.mandatory','false','true/false whether or not the addresshierarchy module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','ce83a857-fcad-4e00-b654-d0d68d6289d5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.soundexProcessor',NULL,'If the Name Phonetics module is installed, this defines the name of a soundex algorithm used by the getPossibleFullAddresses service method.','d18129fb-a14f-4ca5-94bd-9df69f89546f',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.started','true','DO NOT MODIFY. true/false whether or not the addresshierarchy module has been started.  This is used to make sure modules that were running  prior to a restart are started again','047851ad-d4fa-4cee-8499-7064153db21c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.allergen.ConceptClasses','Drug,MedSet','A comma-separated list of the allowed concept classes for the allergen field of the allergy dialog','eaf3f161-3752-412e-9a88-7bba5b702345',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.allergen.drug','162552AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the drug allergens concept','73901ac7-58af-4af7-ba24-84d4fa6cc5b9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
