('allergy.concept.severity.severe','1500AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the SEVERE severity concept','4fa87d11-8875-49d1-87d2-2750397670af',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.unknown','1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the allergy unknown concept','7e0827a8-d31b-4977-9b9a-fd8c2e2725f2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.reaction.ConceptClasses','Symptom','A comma-separated list of the allowed concept classes for the reaction field of the allergy dialog','5362e179-b305-4f3d-a689-1171cfcd5cbc',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('application.name','OpenMRS','The name of this application, as presented to the user, for example on the login and welcome pages.','e7681fbd-f513-40a2-bfdc-0c81c43842f4',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.mandatory','false','true/false whether or not the appointments module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','7f560bae-3f0b-4ee4-ac22-69a1de207ad3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.started','true','DO NOT MODIFY. true/false whether or not the appointments module has been started.  This is used to make sure modules that were running  prior to a restart are started again','995ee21d-d0fa-4ac7-8977-75d9a7bd330f',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointments','/openmrs/ws/rest/v1/appointments/{uuid}','URL pattern to use for published appointment events. Default is /openmrs/ws/rest/v1/appointments/{uuid}. If you change default value, please add your custom implementation for the given URL','37739aee-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointmentService','/openmrs/ws/rest/v1/appointment-services/{uuid}','URL pattern to use for published appointment service events. Default is /openmrs/ws/rest/v1/appointment-services/{uuid}. If you change default value, please add your custom implementation for the given URL','37718206-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForBedTagMap','/openmrs/ws/rest/v1/bedTagMap/{uuid}','URL pattern to use for published bed tag map events. Default is /openmrs/ws/rest/v1/bedTagMap/{uuid}. If you change default value, please add your custom implementation for the given URL.','2fd3d3fb-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForRecurringAppointments','/openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}','URL pattern to use for published Recurring appointment events. Default is /openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}. If you change default value, please add your custom implementation for the given URL','379a835f-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointments','true','If set true, events related to appointment changes are published','37726fa5-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointmentService','true','If set true, events related to appointment service changes are published','37709c78-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForBedTagMapChange','true','If set true, events related to bed tag map changes are published','2fd274af-5bb5-11f1-8ad4-5ed39db8a44e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowedFileExtensions','jpeg,jpg,png,pdf','Comma-separated list of case-insensitive file extensions that are allowed to be uploaded.','601e16c7-9c2f-4511-a309-9dbd596e1e52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowNoCaption','false','Set this property to \'true\' to allow empty attachments\ncaptions','9da88648-a042-443f-b214-362a3ad2d37f',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowWebcam','true','Set this property to \'true\' to allow the use of the\nwebcam for file\nuploads','cf1c9b78-4bd6-427f-aed3-0ea3cb36ffc8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.associateWithVisit','true','If set false, then when uploading an attachment via the \"Attachments Controller\", the visit context will\n*not* be included (and therefore the attachment will not be associated with that visit)','81f4484b-98b4-41f3-b177-0617ea331379',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.conceptComplexUuidList','[\"7cac8397-53cd-4f00-a6fe-028e8d743f8e\",\"42ed45fd-f3f6-44b6-bfc2-8bde1bb41e00\"]','List of concept complex UUIDs that are used in queries\nfor viewing\ndocuments','d5c15629-5097-46ef-9c1c-98c020dee796',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.conceptComplexUuidMap','{\"IMAGE\":\"7cac8397-53cd-4f00-a6fe-028e8d743f8e\",\"OTHER\":\"42ed45fd-f3f6-44b6-bfc2-8bde1bb41e00\"}','Mapping between content families and concept complex\nUUIDs, this is used for\nsaving files based on their MIME type','1d4d56c5-ea25-4680-a6bc-396c20dffc26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.dashboardThumbnailCount','4','Number of thumbnails to display on the dashboard widget','706371d9-3301-4033-a62f-64ef916e2dd3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
